نقش سازمانی: مدیرعامل (ceo)

درخواست کاربر:
پیش‌بینی عملکرد سالانه را می‌خواهم. (مدیرعامل)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "market_data",
      "description": "دادهٔ بازار: قیمت جهانی، نرخ ارز",
      "dimensions": [
        "period"
      ],
      "measures": [
        "lme_price",
        "usd_toman"
      ]
    },
    {
      "dataset": "financial_summary",
      "description": "خلاصهٔ مالی شرکت",
      "dimensions": [
        "period"
      ],
      "measures": [
        "revenue_m",
        "cost_m",
        "profit_m",
        "margin_pct"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "revenue_growth",
      "description": "رشد درآمد",
      "formula": "(درآمد فعلی - درآمد قبل) / درآمد قبل",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "ebitda_margin",
      "description": "حاشیهٔ EBITDA",
      "formula": "EBITDA / درآمد",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "هلدینگ معدنی با چند شرکت تابعه (استخراج، فرآوری، فروش)",
    "هزینه‌ها عمدتاً عملیاتی (سوخت، قطعات، نیرو) و سرمایه‌ای (تجهیزات)",
    "درآمد وابسته به قیمت جهانی LME و نرخ ارز"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "revenue_growth",
      "ebitda_margin"
    ],
    "period": "last_3_months"
  }
}

TOOL_OBSERVATION:
{
  "trend": [
    0.1,
    0.1,
    1.1
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "market_data",
    "filters": {
      "period": "next_year"
    }
  }
}

TOOL_OBSERVATION:
{
  "status": "داده ناقص",
  "available": [
    "روند ۳ ماهه"
  ],
  "missing": [
    "پیش‌بینی قیمت LME",
    "نرخ ارز",
    "برنامهٔ تولید"
  ]
}

نقش سازمانی: مدیرعامل (ceo)

