{
  "data_catalog": [
    {
      "dataset": "market_data",
      "description": "دادهٔ بازار: قیمت جهانی، نرخ ارز",
      "dimensions": [
        "period"
      ],
      "measures": [
        "lme_price",
        "usd_toman"
      ]
    },
    {
      "dataset": "financial_summary",
      "description": "خلاصهٔ مالی شرکت",
      "dimensions": [
        "period"
      ],
      "measures": [
        "revenue_m",
        "cost_m",
        "profit_m",
        "margin_pct"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "revenue_growth",
      "description": "رشد درآمد",
      "formula": "(درآمد فعلی - درآمد قبل) / درآمد قبل",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "هلدینگ معدنی با چند شرکت تابعه (استخراج، فرآوری، فروش)",
    "هزینه‌ها عمدتاً عملیاتی (سوخت، قطعات، نیرو) و سرمایه‌ای (تجهیزات)",
    "درآمد وابسته به قیمت جهانی LME و نرخ ارز"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "revenue_growth",
    "granularity": "month",
    "range": "last_6_months"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "market_data",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "lme_usd": 8993,
  "change_pct": 12
}

نقش سازمانی: مدیرعامل (ceo)

درخواست کاربر:
خلاصهٔ عملکرد ماه را برای هیئت مدیره بده: درآمد، سود، عملیات و ایمنی. (مدیرعامل — هلدینگ سنگ‌آهن ایران)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "financial_summary",
      "description": "خلاصهٔ مالی شرکت",
      "dimensions": [
        "period"
      ],
      "measures": [
        "revenue_m",
        "cost_m",
        "profit_m",
        "margin_pct"
      ]
    },
    {
      "dataset": "operational_kpi",
      "description": "شاخص‌های عملیاتی کلیدی",
      "dimensions": [
        "period"
      ],
      "measures": [
        "extraction_tons",
        "recovery_pct",
        "cost_per_ton"
      ]
    },
    {
      "dataset": "safety_hse",
      "description": "شاخص‌های ایمنی و محیط زیست",
      "dimensions": [
        "period"
      ],
      "measures": [
        "ltifr",
        "trifr",
        "ghg_intensity"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "revenue_growth",
      "description": "رشد درآمد",
      "formula": "(درآمد فعلی - درآمد قبل) / درآمد قبل",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "ebitda_margin",
      "description": "حاشیهٔ EBITDA",
      "formula": "EBITDA / درآمد",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "cost_per_ton",
      "description": "هزینهٔ هر تن",
      "formula": "هزینهٔ کل / تن تولیدی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "ltifr",
      "description": "نرخ حوادث ایمنی",
      "formula": "( حوادث × ۱٬۰۰۰٬۰۰۰ ) / ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "هلدینگ معدنی با چند شرکت تابعه (استخراج، فرآوری، فروش)",
    "هزینه‌ها عمدتاً عملیاتی (سوخت، قطعات، نیرو) و سرمایه‌ای (تجهیزات)",
    "درآمد وابسته به قیمت جهانی LME و نرخ ارز"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "revenue_growth",
      "ebitda_margin",
      "cost_per_ton",
      "ltifr"
    ],
    "period": "this_month"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "financial_summary",
    "filters": {
      "period": "this_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "revenue_m": 1006,
  "cost_m": 704,
  "profit_m": 301.8
}

