حاشیهٔ سود 16% شده. ریشهٔ این افت کجاست؟ (مدیرعامل — هلدینگ سنگ‌آهن ایران)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "financial_summary",
      "description": "خلاصهٔ مالی شرکت",
      "dimensions": [
        "period"
      ],
      "measures": [
        "revenue_m",
        "cost_m",
        "profit_m",
        "margin_pct"
      ]
    },
    {
      "dataset": "operational_kpi",
      "description": "شاخص‌های عملیاتی کلیدی",
      "dimensions": [
        "period"
      ],
      "measures": [
        "extraction_tons",
        "recovery_pct",
        "cost_per_ton"
      ]
    },
    {
      "dataset": "safety_hse",
      "description": "شاخص‌های ایمنی و محیط زیست",
      "dimensions": [
        "period"
      ],
      "measures": [
        "ltifr",
        "trifr",
        "ghg_intensity"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ebitda_margin",
      "description": "حاشیهٔ EBITDA",
      "formula": "EBITDA / درآمد",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "cost_per_ton",
      "description": "هزینهٔ هر تن",
      "formula": "هزینهٔ کل / تن تولیدی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "ltifr",
      "description": "نرخ حوادث ایمنی",
      "formula": "( حوادث × ۱٬۰۰۰٬۰۰۰ ) / ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "هلدینگ معدنی با چند شرکت تابعه (استخراج، فرآوری، فروش)",
    "هزینه‌ها عمدتاً عملیاتی (سوخت، قطعات، نیرو) و سرمایه‌ای (تجهیزات)",
    "درآمد وابسته به قیمت جهانی LME و نرخ ارز"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ebitda_margin",
      "cost_per_ton",
      "ltifr"
    ],
    "period": "curr_month"
  }
}

